package net.civeira.phylax.feature.observe.observedissue.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;

public interface ObservedIssueCacheGateway {

  /**
   * @autogenerated CacheGatewayGenerator
   */
  void evict();

  /**
   * @autogenerated CacheGatewayGenerator
   * @param observedIssue
   */
  void remove(ObservedIssue observedIssue);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param filter
   * @param cursor
   * @return
   */
  Optional<ObservedIssueCached> retrieve(ObservedIssueFilter filter, ObservedIssueCursor cursor);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param filter
   * @param cursor
   * @param observedIssues
   * @return
   */
  ObservedIssueCached store(ObservedIssueFilter filter, ObservedIssueCursor cursor,
      List<ObservedIssue> observedIssues);

  /**
   * @autogenerated CacheGatewayGenerator
   * @param observedIssue
   */
  void update(ObservedIssue observedIssue);
}
